import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, texture } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry, MeshBasicNodeMaterial } = ctx.THREE;

  // Root container (position/rotation/scaling are applied by the adapter)
  const root = new ThreeGroup();

  // Geometry for the card
  const geometry = new PlaneGeometry(7, 6, 1, 1); // size placeholder; spec does not dictate exact size
  // Gradient node: vertical blend between ink and paper
  const gradientNode = mix(
    color(config.visual?.colors?.ink ?? '#16161d'),
    color(config.visual?.colors?.paper ?? '#e8ecf2'),
    uv().y
  );

  // Base material with gradient; texture will be added once loaded
  const material = new MeshBasicNodeMaterial({
    color: gradientNode,
    // map will be assigned later
    transparent: true,
    depthWrite: false
  });

  const plane = new ThreeMesh(geometry, material);
  root.add(plane);

  // Load the brushed metal texture and apply it when ready
  const texturePromise = ctx.textureLoader.loadTexture(
    config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png'
  ).then((tex) => {
    // Combine texture with gradient using multiply for subtle grain effect
    const texNode = texture(tex);
    const combined = mix(gradientNode, texNode, 0.2); // 20% texture blend
    material.color = combined;
    material.map = tex;
    material.needsUpdate = true;
    // Keep reference for cleanup
    cleanupResources.texture = tex;
  }).catch(() => {
    // If texture fails, keep gradient only
  });

  // Store references for cleanup
  const cleanupResources = {
    geometry,
    material,
    texture: null,
    timelines: [] // no GSAP timelines for this node, but kept for pattern
  };

  // Attach empty handlers object (no interactions defined)
  root.userData.handlers = {};

  // Cleanup function
  root.userData.cleanup = () => {
    // Dispose geometry
    if (cleanupResources.geometry) cleanupResources.geometry.dispose();
    // Dispose material
    if (cleanupResources.material) cleanupResources.material.dispose();
    // Dispose texture if it was loaded
    if (cleanupResources.texture) cleanupResources.texture.dispose();
    // Kill any GSAP timelines that might have been added
    cleanupResources.timelines.forEach((t) => t.kill());
    // Cancel any pending texture load promises (no native cancel, rely on disposal)
  };

  return root;
}
